    11	// The high surrogate may be uninitialized if the pair is invalid,
    12	// we choose to ignore the problem to reduce the size of the code
    13	// Garbage in => Garbage out
    14	#if defined(__GNUC__)
    15	#if __GNUC__ >= 7
    16	#pragma GCC diagnostic push
    17	#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
    18	#endif
